write('server/tests/mixedSourceBatchFiveDimensionAcceptance.test.ts', r'''import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import {academyMinervaLab} from '../cpaOrganization/academyMinervaLab.js';import {buildMixedSourceBatchFiveDimensionChecks} from '../cpaOrganization/mixedSourceBatchEvidenceEngine.js';import {prepareMixedSourceBatch} from './fixtures/mixedSourceBatchAcceptanceHelpers.js';import {batchEvidenceDir} from './fixtures/mixedSourceBatchFixture.js';const dir=batchEvidenceDir();const source=JSON.parse(fs.readFileSync(path.join(dir,'source-truth.json'),'utf8'));const product=JSON.parse(fs.readFileSync(path.join(dir,'product-truth.json'),'utf8'));const deliverable=JSON.parse(fs.readFileSync(path.join(dir,'deliverable-truth.json'),'utf8'));assert.equal(source.marker,'P2_MIXED_SOURCE_BATCH_SOURCE_TRUTH=PASS');assert.equal(product.marker,'P2_MIXED_SOURCE_BATCH_PRODUCT_TRUTH_BROWSER=PASS');assert.equal(deliverable.marker,'P2_MIXED_SOURCE_BATCH_DELIVERABLE_TRUTH=PASS');const p=await prepareMixedSourceBatch();const checks=buildMixedSourceBatchFiveDimensionChecks(p.validReview,p.tamperedReview);const report=academyMinervaLab.evaluateFiveDimensions({caseId:'CURR-MIXED-SOURCE-BATCH',executionId:`batch-${p.sourceShas.SPREADSHEET.slice(0,12)}`,dimensions:{SOURCE_COVERAGE:{checks:checks.source},SEMANTIC_UNDERSTANDING:{checks:checks.semantic},ACCOUNTING_ACCURACY:{checks:checks.accounting},PRODUCT_TRUTH:{checks:[{checkId:'batch-real-product-browser',label:'Actual Eve product shows all four source families and blocks cross-document coordinate substitution',outcome:'PASS',evidenceRefs:[`browser:${product.screenshot}`,...Object.values(product.sourceShas).map((s:any)=>`source:${s}`)],details:[`status=${product.status}; promotion=${product.promotionState}`]}]},DELIVERABLE_TRUTH:{checks:[{checkId:'batch-artifact-lineage',label:'PDF JSON CSV and XLSX preserve all four source lineages plus blocked batch identity state',outcome:'PASS',evidenceRefs:[`artifact:pdf:${deliverable.formats.pdf}`,`artifact:json:${deliverable.formats.json}`,`artifact:xlsx:${deliverable.formats.xlsx}`,`artifact:csv:${deliverable.formats.csv}`],details:[`report=${deliverable.reportId}:${deliverable.version}`]}]}}});for(const d of ['SOURCE_COVERAGE','SEMANTIC_UNDERSTANDING','ACCOUNTING_ACCURACY','PRODUCT_TRUTH','DELIVERABLE_TRUTH'] as const)assert.equal(report.dimensions[d].status,'PASS',`${d} must pass`);assert.equal(report.passedDimensionCount,5);assert.equal(report.notTestedDimensionCount,0);assert.equal(report.fullyTested,true);assert.equal(report.allRequiredDimensionsPassed,true);assert.equal(report.overallStatus,'FIVE_DIMENSION_PASS');fs.writeFileSync(path.join(dir,'five-dimension-result.json'),JSON.stringify({marker:'P2_MIXED_SOURCE_BATCH_FIVE_DIMENSION_PASS=PASS',sourceShas:p.sourceShas,report},null,2));console.log('P2_MIXED_SOURCE_BATCH_FIVE_DIMENSION_PASS=PASS');
''')

